"use strict";
GUIDE_DATA_EN.sections.push({"id":"g96","part":10,"title":"Project Tasks","blocks":[{"level":1,"text":"Work packages are generated by a WBS, and user stories are generated by a backlog"},{"level":1,"text":"In project management, a task is a specific action taken to complete a deliverable"},{"level":1,"text":"Tasks are not visualized at the WBS or user story level"},{"level":1,"text":"Tasks are not always required for every work package or user story"},{"level":1,"text":"Some guidelines to help determine when to create tasks"},{"level":2,"text":"If the team wanted a to-do list to manage available work"},{"level":2,"text":"If a work package has multiple actions with different owners"},{"level":2,"text":"If there are multiple dependencies within a user story or work package"},{"level":2,"text":"If it improves how the team works or how to manage the project"}]},{"id":"g97","part":10,"title":"Dependencies","blocks":[{"level":1,"text":"Defining project activities is a crucial step in creating a project schedule"},{"level":1,"text":"Dependencies"},{"level":2,"text":"Refer to the relationships between activities"},{"level":2,"text":"Dependencies control the order of events in a project"},{"level":1,"text":"When two activities are dependent on each other, they have a predecessor- successor relationship"},{"level":1,"text":"Dependencies can be visualized in multiple ways, including listing predecessors for each dependency in a project schedule, or through Gantt charts and project network diagrams"},{"level":1,"text":"4 Types of Dependencies"},{"level":2,"text":"Finish-to-Start (FS)"},{"level":2,"text":"Activity 2 starts after Activity 1 finishes"},{"level":2,"text":"Start-to-Start (SS)"},{"level":2,"text":"Activity 2 starts after Activity 1 begins"},{"level":2,"text":"Finish-to-Finish (FF)"},{"level":2,"text":"Activity 2 finishes after Activity 1 finishes"},{"level":2,"text":"Start-to-Finish (SF)"},{"level":2,"text":"Activity 2 finishes only after Activity 1 has started"},{"level":1,"text":"On a diagram or Gantt chart, the relationship type determines how to link two activities visually"},{"level":1,"text":"4 Types of Logic Dependencies"},{"level":2,"text":"Mandatory"},{"level":2,"text":"Inevitable and often arises due to legal or contractual reasons"},{"level":2,"text":"Discretionary"},{"level":2,"text":"Often represents a strategy for optimizing efficiency, lowering costs, or improving quality"},{"level":2,"text":"External"},{"level":2,"text":"Beyond the control of the organization"},{"level":2,"text":"Internal"},{"level":2,"text":"One that the organization can control"},{"level":1,"text":"No type of dependency is inherently better than the others"},{"level":1,"text":"Mandatory dependencies are often inflexible and easier to manage, but they are also higher risk"},{"level":1,"text":"Understanding the details of each dependency helps to ensure that the project stays compliant while managing tradeoffs"}]},{"id":"g98","part":10,"title":"Estimation Techniques","blocks":[{"level":1,"text":"Estimates are extremely valuable because they give you a starting point for your project"},{"level":1,"text":"There are different techniques for estimating project costs and durations, each with its advantages and limitations"},{"level":1,"text":"Some of the most common techniques for estimating project costs and durations"},{"level":2,"text":"Top-Down Estimating"},{"level":2,"text":"Starts by estimating the total cost or duration of the project or major deliverables and then breaks down the estimate into smaller components"},{"level":2,"text":"Bottom-Up Estimating"},{"level":2,"text":"Estimates the cost or duration of each individual activity, task, or user story and then aggregates them to produce a project estimate"},{"level":2,"text":"Analogous Estimating"},{"level":2,"text":"Uses historical data from similar projects to estimate the cost or duration of the current project"},{"level":2,"text":"Parametric Model Estimating"},{"level":2,"text":"Combines historical data with mathematical models to estimate the cost or duration of a project"},{"level":2,"text":"Combining three-point estimation with any other estimating technique can provide a more nuanced and accurate estimate"},{"level":2,"text":"This approach considers multiple possible scenarios and calculates an average estimate based on three values: optimistic, pessimistic, and most likely"},{"level":2,"text":"Here's an example of using three-point estimation"},{"level":2,"text":"Suppose a team is estimating the time required to complete a software development project. Using the three-point estimation technique, they determine the following estimates"},{"level":2,"text":"Optimistic estimate (O): 4 months"},{"level":2,"text":"Most likely estimate (M): 6 months"},{"level":2,"text":"Pessimistic estimate (P): 8 months"},{"level":2,"text":"To calculate the average estimate, they can use the formula"},{"level":2,"text":"( O + 4M + P ) / 6"},{"level":2,"text":"In this case, the average estimate would be"},{"level":2,"text":"(4 + 4(6) + 8) / 6 = 5.33 months"},{"level":2,"text":"This estimate considers the best-case, worst-case, and most likely scenarios, providing a more comprehensive and accurate estimate"},{"level":2,"text":"How about estimating time and effort?"},{"level":2,"text":"One common approach is to estimate time and effort for project activities, such as using duration and task hours or story points"}]},{"id":"g99","part":10,"title":"Resource Allocation","blocks":[{"level":1,"text":"Resource Allocation"},{"level":2,"text":"It involves allocating both human and physical resources, as capital resources are typically used to pay for them"},{"level":2,"text":"It provides numerous benefits to a project"},{"level":2,"text":"Clarity"},{"level":2,"text":"Parity"},{"level":2,"text":"Discovery"},{"level":2,"text":"Validity"},{"level":1,"text":"The resource assignment process involves two activities"},{"level":2,"text":"Assigning roles via a Responsibilities Assignment Matrix (RAM)"},{"level":2,"text":"Assigning human and physical resources using a project scheduling tool"},{"level":1,"text":"During the project initiation phase, the Matrix (RAM) is initiated and team members with their respective roles are added"},{"level":1,"text":"The RACI Matrix consists of four roles which are as follows"},{"level":2,"text":"Responsible (R)"},{"level":2,"text":"The person who will perform the assigned work"},{"level":2,"text":"Accountable (A)"},{"level":2,"text":"The person who will be responsible for the final work"},{"level":2,"text":"Consulted (C)"},{"level":2,"text":"The person who can provide expertise on the work but will not be directly involved"},{"level":2,"text":"Informed (I)"},{"level":2,"text":"The person who needs to be aware of the work completion"},{"level":1,"text":"Responsibility Assignment Matrix (RAM) is a crucial tool for defining project roles and responsibilities"},{"level":1,"text":"To effectively manage project resources, a project management scheduling tool should also be utilized"},{"level":2,"text":"Most projects employ project software to create schedules, determine baselines, and report on project outcomes"},{"level":2,"text":"This scheduling software typically includes a comprehensive list"},{"level":2,"text":"Project Activities"},{"level":2,"text":"Milestones"},{"level":2,"text":"Dependencies"},{"level":2,"text":"Corresponding Dates"},{"level":2,"text":"This information can be visualized using tables, Kanban boards, and Gantt charts"},{"level":2,"text":"The software also maintains a resource list that includes all project resources, their capacity, and associated costs"},{"level":1,"text":"Tracking resource assignments can help identify potential issues"},{"level":1,"text":"Project Schedule"},{"level":2,"text":"Contains the activities required to complete the project work"},{"level":2,"text":"Project Timeline"},{"level":2,"text":"Resources"},{"level":2,"text":"Due Dates"},{"level":2,"text":"Dependencies Creating a Project Plan"}]},{"id":"g100","part":10,"title":"Creating a Project Plan","blocks":[{"level":1,"text":"The goal of gathering metrics is to improve an outcome"},{"level":1,"text":"Project Network Diagrams"},{"level":2,"text":"Visually represent the logical relationships and dependencies between project activities"},{"level":1,"text":"Critical Path Method"},{"level":2,"text":"Technique that identifies the longest sequence of dependent activities, to determine the project's minimum duration and highlight activities that must be closely monitored"},{"level":1,"text":"Minimum Viable Product"},{"level":2,"text":"Refers to the development of a basic version of a product or solution that includes only the core features necessary to deliver value to early users or customers"},{"level":1,"text":"Project Reserves"},{"level":2,"text":"Allocated resources, such as time, budget, or contingency plans, set aside to address unforeseen risks, uncertainties, or changes during the project execution"},{"level":1,"text":"Project Baselines"},{"level":2,"text":"The approved and agreed-upon reference points that define the initial scope, schedule, and cost of a project"},{"level":1,"text":"Project Budget"},{"level":2,"text":"Represent the planned financial resources allocated for executing a project, encompassing estimated costs for labor, materials, equipment, and other expenses"}]},{"id":"g101","part":10,"title":"Project Network Diagrams","blocks":[{"level":1,"text":"As part of project management, it is a need to create a schedule that included all project activities, dependencies, and time estimates"},{"level":1,"text":"The project schedule is commonly presented as a spreadsheet or Gantt chart"},{"level":2,"text":"Gantt chart uses bars to represent activity duration, the resulting chart can be cumbersome to view"},{"level":2,"text":"Project Network Diagram"},{"level":2,"text":"Also known as a project schedule network diagram, provides a clear and concise visual representation of the project schedule using arrows and same-sized rectangles"},{"level":1,"text":"Different Diagram Methods"},{"level":2,"text":"Precedence Diagram Method (PDM)"},{"level":2,"text":"A commonly used project diagram style that utilizes rectangles and arrows to indicate dependencies between activities"},{"level":2,"text":"A PDM chart can be sketched and layered with duration and calculations using another diagram technique"},{"level":2,"text":"Program Evaluation and Review Technique (PERT)"},{"level":2,"text":"Designed to illustrate the duration, activities, and dependencies of a project"},{"level":2,"text":"It involves using the three duration estimates for each activity"},{"level":2,"text":"Optimistic"},{"level":2,"text":"Pessimistic"},{"level":2,"text":"Most Likely"},{"level":2,"text":"A PERT estimate is helpful for calculating realistic timing estimates"},{"level":2,"text":"Critical Path Method (CPM)"}]},{"id":"g102","part":10,"title":"Critical Path Method","blocks":[{"level":1,"text":"Critical Path Method (CPM)"},{"level":2,"text":"Utilized in a project network diagram to incorporate duration, activities, dependencies, PERT estimates, and additional calculations"},{"level":1,"text":"To calculate the critical path, it is necessary to identify the longest chain of dependent activities, which may not necessarily be the most important activities in terms of value delivery"},{"level":1,"text":"7 Steps of Critical Path Analysis"},{"level":2,"text":"Draw the project activities and dependencies"},{"level":2,"text":"Calculate the PERT estimate duration for each activity"},{"level":2,"text":"Complete a forward pass to calculate the early start and early finish"},{"level":2,"text":"Complete a backward pass to calculate the late start and late finish"},{"level":2,"text":"Calculate the total float (TF)"},{"level":2,"text":"Total Float (TF)"},{"level":2,"text":"Calculated by subtracting the activity’s earliest finish date from its latest finish date"},{"level":2,"text":"Calculate the free float (FF)"},{"level":2,"text":"Free Float (FF)"},{"level":2,"text":"Calculated by subtracting the activity’s earliest finish date from its earliest start date"},{"level":2,"text":"Identify the critical path"},{"level":2,"text":"Critical Path"},{"level":2,"text":"The sequence of activities that must be completed on time to meet the project’s deadline"},{"level":1,"text":"By using critical path analysis, you can ensure that the project stays on track, and the project team is focusing on the most critical activities"},{"level":1,"text":"The critical path is the longest path through the network diagram in terms of duration"},{"level":1,"text":"CPM is a project management technique used to determine the sequence of dependent activities with the longest duration in a project"}]},{"id":"g103","part":10,"title":"Usefulness of CPM Outputs","blocks":[{"level":1,"text":"Critical Path Analysis (CPA)"},{"level":2,"text":"Project management technique that helps to plan, schedule, and manage complex projects effectively"},{"level":1,"text":"The critical path represents the longest duration of the project and helps in identifying the activities that are critical to the project's success"},{"level":1,"text":"5 Main Benefits of Conducting CPA"},{"level":2,"text":"Efficient resource allocation"},{"level":2,"text":"Allows project managers to identify the critical activities that require the most attention and resources, which helps in effective resource allocation"},{"level":2,"text":"Accurate project completion time estimation"},{"level":2,"text":"Conducting a critical path analysis helps project managers to estimate the time required to complete the project accurately"},{"level":2,"text":"Improved project visibility"},{"level":2,"text":"Provides a visual representation of the project's critical path, which allows project managers to identify potential bottlenecks and delays"},{"level":2,"text":"Better risk management"},{"level":2,"text":"The critical path analysis helps project managers to identify the critical activities that are most susceptible to risks and delays"},{"level":2,"text":"Improved communication"},{"level":2,"text":"Provides a clear and concise representation of the project's critical path, which helps in communicating the project's status and progress to stakeholders"},{"level":1,"text":"7 Steps of Critical Path Analysis"},{"level":2,"text":"Draw the project activities and dependencies"},{"level":2,"text":"Calculate the PERT estimate duration for each activity"},{"level":2,"text":"Complete a forward pass to calculate the early start and early finish"},{"level":2,"text":"During the forward pass, you will determine two values for each activity: the early start and the early finish"},{"level":2,"text":"Early Start (ES)"},{"level":2,"text":"The earliest possible start time for an activity, based on the time required to finish all predecessor activities"},{"level":2,"text":"Early Finish (EF)"},{"level":2,"text":"The earliest possible finish time for an activity based on its duration"},{"level":2,"text":"The following formulas can be used to calculate ES and EF"},{"level":2,"text":"ES = Maximum EF of all direct predecessors"},{"level":2,"text":"EF = ES + t, where t represents the activity’s duration"},{"level":2,"text":"Complete a backward pass to calculate the late start and late finish"},{"level":2,"text":"During a backward pass, you will begin at the end of the project and work backward through the dependencies until you reach the start of the project"},{"level":2,"text":"For each activity, you will calculate two new values during the backward pass: the late start and the late finish"},{"level":2,"text":"Late Start (LS)"},{"level":2,"text":"The latest possible start time for an activity that still allows the project to finish on time"},{"level":2,"text":"Late Finish (LF)"},{"level":2,"text":"The latest possible finish time for an activity that still allows the project to finish on time"},{"level":2,"text":"To calculate LS and LF, use the following formulas"},{"level":2,"text":"LF = minimum LS of all successors"},{"level":2,"text":"LS = LF – t, where t represents the activity’s duration"},{"level":2,"text":"The backward pass uses the smallest LF because it represents the longest amount of time that lies ahead in the project"},{"level":2,"text":"Calculate the total float (TF)"},{"level":2,"text":"Total Float (TF)"},{"level":2,"text":"Measures the amount of time an activity can be delayed without affecting the project's overall timeline"},{"level":2,"text":"TF is calculated for each activity using either of the following formulas"},{"level":2,"text":"TF = LS – ES"},{"level":2,"text":"TF = LF – EF"},{"level":2,"text":"Calculate the free float (FF)"},{"level":2,"text":"Free Float (FF)"},{"level":2,"text":"The amount of time an activity can wait before starting without impacting any other activities"},{"level":2,"text":"Take the minimum early start of all direct successors minus the early finish for the task that is being calculated"},{"level":2,"text":"Identify the critical path"},{"level":2,"text":"The critical path is defined as the list of all activities where the total float is equal to zero"},{"level":1,"text":"At a high level, everything seems to be a critical path item, but in reality, there are only certain parts of a task that become a critical path item"},{"level":1,"text":"CPM is a technique that helps plan, schedule, and manage complex projects effectively by identifying the critical path"}]},{"id":"g104","part":11,"title":"Minimum Viable Product","blocks":[{"level":1,"text":"Minimum Viable Product (MVP)"},{"level":2,"text":"Initial version of a product that demonstrates enough functionality for early adopters to use and provide feedback"},{"level":1,"text":"When stakeholders see a genuine, working product early in the project, it can also build confidence in the project's success"},{"level":1,"text":"Different Features of MVP"},{"level":2,"text":"Project Creation"},{"level":2,"text":"Allow users to create new projects, set project goals and deadlines, and assign team members to work on the project"},{"level":2,"text":"Task Management"},{"level":2,"text":"Allow users to create tasks within a project, assign them to team members, set deadlines and track progress"},{"level":2,"text":"Calendar View"},{"level":2,"text":"Allows users to view the project timelines, deadlines, and team schedules in a calendar view to help manage project schedules"},{"level":2,"text":"Communication"},{"level":2,"text":"Includes an in-app messaging feature that would allow team members to communicate with each other"},{"level":2,"text":"Reporting"},{"level":2,"text":"Allows users to see project progress and completion rates, track time spent on tasks, and generate reports on project status"},{"level":1,"text":"The MVP would provide a basic set of tools for an IT project manager to manage projects, communicate with team members, and track progress"},{"level":1,"text":"During the project initiation phase, a preliminary scope statement is prepared"},{"level":1,"text":"As the project progresses, the team gains more knowledge about the project's scope and requirements, allowing them to create a more detailed scope statement"},{"level":2,"text":"The same template can be used for both preliminary and detailed scope statements, but the latter may include additional fields such as significant project risks, milestones, and vendor requirements"},{"level":2,"text":"Creating a detailed scope statement provides an opportunity to validate the project plan against the preliminary scope statement"},{"level":2,"text":"The following fields are commonly included in a scope statement"},{"level":2,"text":"Project Scope Description"},{"level":2,"text":"Project Acceptance Criteria"},{"level":2,"text":"Project Deliverables"},{"level":2,"text":"Project Exclusions"},{"level":2,"text":"Assumptions"},{"level":2,"text":"Constraints"},{"level":2,"text":"It might include additional fields such as"},{"level":2,"text":"Milestones"},{"level":2,"text":"Requirements"},{"level":2,"text":"Tasks"},{"level":2,"text":"Risks"},{"level":2,"text":"Budget"},{"level":2,"text":"Estimates"},{"level":2,"text":"Estimation Methods"},{"level":1,"text":"Cost Estimates"},{"level":2,"text":"Project costs consist of both direct and indirect costs"},{"level":2,"text":"Direct Costs"},{"level":2,"text":"Incurred as a direct result of the project and can be linked to a specific resource or activity"},{"level":2,"text":"Indirect Costs"},{"level":2,"text":"Overhead expenses that support multiple operations that cannot be attributed directly to a specific resource or activity"},{"level":2,"text":"When estimating project costs, direct costs are always included, and resource cost rates are required for cost aggregation"},{"level":1,"text":"The scope statement evolves from a preliminary version to a detailed version throughout the project"},{"level":1,"text":"Cost estimation involves considering direct and indirect costs, using resource cost rates to estimate expenses at different levels of the project"}]},{"id":"g105","part":11,"title":"Project Reserves","blocks":[{"level":1,"text":"During your project execution, unforeseen circumstances can arise, and project budgets need to include financial reserves to safeguard against setbacks"},{"level":1,"text":"2 Types of Reserves"},{"level":2,"text":"Contingency Reserve"},{"level":2,"text":"A calculated buffer of time and cost that covers documented risks (“known unknowns”)"},{"level":2,"text":"Contingency reserve is also known as a “contingency buffer”"},{"level":2,"text":"Management Reserve"},{"level":2,"text":"An additional amount of time or money that serves as a contingency for “unknown unknowns”"},{"level":2,"text":"When requesting management reserves, provide a thorough justification and recovery plan"},{"level":2,"text":"Management reserves are meant to cover significant project changes"},{"level":2,"text":"Switching vendors"},{"level":2,"text":"Onboarding time"},{"level":2,"text":"Contract changes"},{"level":2,"text":"Resource cost changes"},{"level":2,"text":"Global supply chain issues"},{"level":1,"text":"The reserve provides backup funding for the project in case any of the identified risks materialize"}]},{"id":"g106","part":11,"title":"Calculating Project Reserves","blocks":[{"level":1,"text":"Various methods to calculate project reserves"},{"level":2,"text":"Percentage of a Project’s Cost"},{"level":2,"text":"A percentage of the estimated cost of the project is taken into consideration"},{"level":2,"text":"Monte Carlo Analysis"},{"level":2,"text":"A well-known simulation technique that employs a three-point estimate to construct a probability distribution"},{"level":2,"text":"It tallies the frequency of overall project outcomes"},{"level":2,"text":"It overlays a cumulative probability line on the histogram to indicate the probability of the project staying within budget"},{"level":2,"text":"Expected Monetary Value (EMV)"},{"level":2,"text":"Requires each risk’s probability and impact assessment"},{"level":2,"text":"The probability and the financial impact of its occurrence are multiplied for each risk"},{"level":2,"text":"EMV = Probability x Impact"},{"level":2,"text":"The EMV calculation helps companies make decisions"},{"level":2,"text":"Decision Tree Analysis"},{"level":2,"text":"A decision-making tool for contingency planning (quantitative decision-making)"},{"level":2,"text":"A decision tree has three components: decision, options, and outcomes"},{"level":2,"text":"To calculate the EMV for each outcome, add up the EMV for each option's outcome to determine the EMV cost"},{"level":2,"text":"Decision tree analysis is best suited for large projects with high- impact and high-probability risks"}]},{"id":"g107","part":11,"title":"Project Baselines","blocks":[{"level":1,"text":"Project Baseline"},{"level":2,"text":"Serves as the initial reference point for the project"},{"level":1,"text":"A project baseline consists of three parts"},{"level":2,"text":"Scope Baseline"},{"level":2,"text":"Original scope from the detailed scope statement"},{"level":2,"text":"Schedule Baseline"},{"level":2,"text":"Total project duration captured from the project schedule"},{"level":2,"text":"Cost Baseline"},{"level":2,"text":"Expected costs plus the contingency reserves"},{"level":1,"text":"Baselining helps to prevent scope creep, cost overruns, and delays in a project"},{"level":1,"text":"Creating a project baseline results in better estimation and tracking of project progress"},{"level":1,"text":"A good baseline aids in the change control process by serving as the source of truth for the original scope"},{"level":1,"text":"4 Main Steps in Creating a Project Baseline"},{"level":2,"text":"Define the scope and identify key deliverables"},{"level":2,"text":"Review the detailed scope statement and pinpoint the essential deliverables that determine the project's scope"},{"level":2,"text":"Establish a schedule with a project duration and deadline"},{"level":2,"text":"Create the schedule baseline and define the total duration of the project"},{"level":2,"text":"Create the cost baseline"},{"level":2,"text":"Sum up the project cost estimate in contingency reserve"},{"level":2,"text":"Obtain stakeholder approval"},{"level":2,"text":"Share with stakeholders to gain their buy-in"}]},{"id":"g108","part":11,"title":"Project Budgets","blocks":[{"level":1,"text":"The project budget comprises all resource expenses and represents the overall cost of the project, incorporating the cost estimate, contingency reserve, and management reserve"},{"level":1,"text":"A well-defined budget adds impartiality to financial decision-making, which can assist in overcoming resistance"},{"level":1,"text":"Budget Constraint"},{"level":2,"text":"Refers to the limit or restriction placed on the amount of money available for a project"},{"level":1,"text":"Reserves"},{"level":2,"text":"Refer to funds that are set aside to cover unexpected expenses or risks that may arise during the project's lifespan"},{"level":1,"text":"Updating the budget when changes occur is vital"},{"level":1,"text":"Documentation is another essential component of managing a project budget"},{"level":1,"text":"Recording updates to estimates and the use of reserves is also important"},{"level":1,"text":"Keeping the budget updated is critical"},{"level":2,"text":"Changes can occur at any time during the project, and it's easy to forget details"},{"level":1,"text":"Budget constraints are vital to the success of a project"},{"level":2,"text":"Managing reserves, maintaining documentation, and keeping the budget updated are all critical components of ensuring that the project stays on track and within the available resources Procuring Solutions"}]},{"id":"g109","part":11,"title":"Quality Assurance Plan Overview","blocks":[{"level":1,"text":"Quality Assurance (QA)"},{"level":2,"text":"Encompasses a range of procedures that can impact every aspect of a project"},{"level":2,"text":"The distinction between QA and QC can be unclear"},{"level":2,"text":"QA"},{"level":2,"text":"Processes and protocols"},{"level":2,"text":"QC"},{"level":2,"text":"Inspecting finished work"},{"level":1,"text":"QA Plan"},{"level":2,"text":"Developed during the planning phase and remains relevant throughout the project's duration"},{"level":2,"text":"The QA plan addresses several crucial questions"},{"level":2,"text":"How to verify that project work meets expectations?"},{"level":2,"text":"How to prevent quality defects?"},{"level":2,"text":"How to recognize and improve ineffective processes?"},{"level":1,"text":"Verification"},{"level":2,"text":"Internal process that objectively confirms that the deliverable meets quality standards"},{"level":1,"text":"Validation"},{"level":2,"text":"Subjective process that occurs outside the team and focuses on the finished deliverables"},{"level":1,"text":"Verification measures internal quality, while validation measures desirability"},{"level":1,"text":"The QA Plan includes the following components"},{"level":2,"text":"Quality Standards"},{"level":2,"text":"Document any relevant industry or regulatory standards, such as health codes, that apply to the project"},{"level":2,"text":"Quality Objectives"},{"level":2,"text":"Create a list of measurable quality targets, including on-time delivery and the number of defects"},{"level":2,"text":"Roles and Responsibilities"},{"level":2,"text":"Identify the individuals responsible for managing the program, adhering to standards, and evaluating products against the standards"},{"level":2,"text":"Deliverables and Approach"},{"level":2,"text":"Identify all deliverables and processes that are subject to QA activities"},{"level":1,"text":"Regular meetings should be held by the project team to assess their performance and improve"},{"level":2,"text":"Agile methodologies refer to this practice as “retrospectives,” while the more general term is “lessons learned”"},{"level":2,"text":"Lessons learned can refer to the end-of-project reflections"},{"level":2,"text":"At the end of the project aim to improve future projects"},{"level":2,"text":"Retrospectives and lessons learned events are recorded in a lesson learned document"},{"level":1,"text":"Inspection"},{"level":2,"text":"Type of QC tool that involves examining a finished product and comparing it to the expected result"},{"level":2,"text":"Sprint reviews, retrospectives, and software testing are all examples of inspections within a project's quality plan"},{"level":1,"text":"Audit"},{"level":2,"text":"Reviews processes to identify potential sources of quality issues"},{"level":2,"text":"Audit findings occur before work is produced"},{"level":1,"text":"Procurement Process"},{"level":2,"text":"Involves obtaining goods and services from external sources through various methods"},{"level":2,"text":"The procurement process encompasses several steps"},{"level":2,"text":"Defining requirements"},{"level":2,"text":"Submitting purchase requisitions"},{"level":2,"text":"Soliciting quotes or proposals from vendors"},{"level":2,"text":"Evaluating and selecting vendors"},{"level":2,"text":"Managing orders"},{"level":2,"text":"Maintaining records and payments"},{"level":2,"text":"Purchase orders, master service agreements, and procurement contracts are common artifacts involved in the procurement process"},{"level":1,"text":"In the evaluation process for solutions, Statement of Work (SOW), Terms of Reference (TOR), and Market Research are crucial factors for optimizing vendor and product selection"},{"level":2,"text":"Statement of Work (SOW)"},{"level":2,"text":"Formal document that specifies the work a vendor is required to complete, defining the project's scope and technical requirements"},{"level":2,"text":"Terms of Reference (TOR)"},{"level":2,"text":"Focuses on the relationship between the parties involved and emphasizes delivering work"},{"level":2,"text":"Market Research"},{"level":2,"text":"Conducted by procurement specialists about products, services, suppliers, and industry trends"},{"level":1,"text":"Evaluating alternative solutions and considering capital expenses (CapEx) and operational expenses (OpEx) provides flexibility in finding the most suitable options"},{"level":1,"text":"There are three main types of contracts that project managers encounter"},{"level":2,"text":"Fixed-price"},{"level":2,"text":"Establishes a set price for a fixed scope of work and places most of the contract risk on the vendor"},{"level":2,"text":"There are three types"},{"level":2,"text":"Firm fixed-price"},{"level":2,"text":"Fixed-price plus incentive fee"},{"level":2,"text":"Fixed-price with economic price adjustment"},{"level":2,"text":"Cost-plus"},{"level":2,"text":"Reimburses the vendor for all resource costs and adds a fee for profit"},{"level":2,"text":"Cost-plus fixed fee"},{"level":2,"text":"Cost-plus incentive fee"},{"level":2,"text":"Cost-plus award fee"},{"level":2,"text":"Cost-plus percentage of cost"},{"level":2,"text":"Hybrid"},{"level":2,"text":"Combines fixed and cost-plus features"},{"level":1,"text":"Contract terms like warranties and non-disclosure agreements are important in procurement"},{"level":2,"text":"Warranties provide assurance that the vendor will address defects"},{"level":2,"text":"Non-disclosure agreements protect confidential information"},{"level":1,"text":"The project manager plays a role in managing vendor relationship"}]},{"id":"g110","part":11,"title":"Types of Software Tests","blocks":[{"level":1,"text":"Software testing is crucial for IT organizations because it helps ensure that the software being developed meets the requirements and works as intended"},{"level":1,"text":"Some reasons why software testing is important for IT organizations"},{"level":2,"text":"Quality Assurance"},{"level":2,"text":"Verifies and validates the software, ensuring it meets the desired quality standards"},{"level":2,"text":"Cost-effective"},{"level":2,"text":"Detects and fixes bugs during the development phase"},{"level":2,"text":"User Satisfaction"},{"level":2,"text":"Ensures the software meets the user's requirements and expectations"},{"level":2,"text":"Compliance"},{"level":2,"text":"Ensures the software meets the requirements, reducing the risk of legal and financial penalties"},{"level":2,"text":"Reputation"},{"level":2,"text":"Helps to prevent incidents by maintaining the organization's reputation and credibility"},{"level":1,"text":"The tests can be categorized into two types"},{"level":2,"text":"Manual"},{"level":2,"text":"Involves a person manually completing each step of the test, one clicks at a time"},{"level":2,"text":"Manual testing is highly adaptable, as humans can detect slight changes in software appearance"},{"level":2,"text":"Automated"},{"level":2,"text":"Involves machines completing tests through software scripts that flag errors for developers to address"},{"level":2,"text":"Automated tests require human intervention to build and maintain"},{"level":1,"text":"Unit Testing"},{"level":2,"text":"Involves testing the smallest functional unit to ensure its functionality"},{"level":1,"text":"Regression Testing"},{"level":2,"text":"Involves running existing tests after a code change to ensure that the change does not affect any existing functionality"},{"level":1,"text":"Smoke Testing"},{"level":2,"text":"A high-level system test that confirms that the main features of the software are working before detailed testing is conducted"},{"level":1,"text":"User Acceptance Testing"},{"level":2,"text":"Evaluates the final outputs against specifications to determine if a user would accept the product"},{"level":1,"text":"Performance Testing"},{"level":2,"text":"Evaluates the system's stability and speed under various workloads"},{"level":1,"text":"Stress Testing"},{"level":2,"text":"A testing approach that evaluates the system's stability and speed under various workloads"}]},{"id":"g111","part":11,"title":"Create a Test Plan","blocks":[{"level":1,"text":"The test plan includes the test strategy, a specific schedule of events, tests to run, and manual and automated tests"},{"level":1,"text":"Transparency ensures a shared understanding of the product's quality expectations"},{"level":1,"text":"Test plans are reusable, as every development project includes User Acceptance Testing (UAT)"},{"level":1,"text":"There are several elements in a test plan"},{"level":2,"text":"Scope"},{"level":2,"text":"Provides an overview of the project scope, including objectives, exclusions, and other scenarios"},{"level":2,"text":"Test Type"},{"level":2,"text":"Identifies the types of tests used in the project, what the tests are for, and when they are used"},{"level":2,"text":"Schedule"},{"level":2,"text":"Outlines the start and end dates for testing and the dates for each test category"},{"level":2,"text":"Resources"},{"level":2,"text":"Lists the required systems and personnel needed to complete the testing process and the roles and responsibilities of team members"},{"level":2,"text":"Environment"},{"level":2,"text":"Outlines the configurations, hardware, and software required to create a test environment"},{"level":2,"text":"Tools"},{"level":2,"text":"Lists all the software requirements needed for building and running tests, and reports test results, records defects, and shares progress"},{"level":2,"text":"Defect Management"},{"level":2,"text":"Outlines clear expectations for defect handling, including system to use for recording, when to record a defect, and what information to capture"},{"level":2,"text":"Risk Management"},{"level":2,"text":"Summarizes the risks relevant to the testing process, including new risks discovered during the execution of the test plan"},{"level":2,"text":"Exit Parameter"},{"level":2,"text":"Sets the standard that the QA team measures against and the development team writes against"},{"level":1,"text":"Different validation activities"},{"level":2,"text":"Service Level Agreements (SLA)"},{"level":2,"text":"Service contract that outlines performance expectations and consequences for not meeting expectations"},{"level":2,"text":"SLA cannot guarantee a specific level of performance"},{"level":2,"text":"Many SLAs are associated with on-time service or system performance, improving schedules"},{"level":2,"text":"Post-implementation Support"},{"level":2,"text":"Provides adoption assistance after the go-live date"},{"level":2,"text":"Post-implementation support in the project plan is crucial because it's often overlooked after implementation"},{"level":2,"text":"Post-implementation support differs from technical support"},{"level":2,"text":"Warranty"},{"level":2,"text":"A contractual obligation that guarantees a product meets specific requirements"},{"level":2,"text":"Warranties require resources for support throughout the warranty period"}]},{"id":"g112","part":12,"title":"Project Management Plan","blocks":[{"level":1,"text":"The project management plan encompasses a series of documents that detail the project team's deliverables, approach, and performance metrics"},{"level":1,"text":"Project Plan"},{"level":2,"text":"A dynamic resource that evolves throughout the project lifecycle"},{"level":1,"text":"The project sponsor, project manager, and functional managers must approve the project plan"},{"level":1,"text":"The Project Management Plan has the following contents, over them briefly and their subordinate components"},{"level":2,"text":"Introduction"},{"level":2,"text":"Background"},{"level":2,"text":"Purpose of the Plan"},{"level":2,"text":"Scope of the Plan"},{"level":2,"text":"Project Scope Statement"},{"level":2,"text":"Project Objectives"},{"level":2,"text":"Deliverables"},{"level":2,"text":"Scope Exclusions"},{"level":2,"text":"Assumptions and Constraints"},{"level":2,"text":"Acceptance Criteria"},{"level":2,"text":"Work Breakdown Structure (WBS) or Backlog"},{"level":2,"text":"WBS or Backlog Description"},{"level":2,"text":"WBS or Backlog Hierarchy"},{"level":2,"text":"WBS or Backlog Dictionary"},{"level":2,"text":"Resource Plan"},{"level":2,"text":"Resource Requirements"},{"level":2,"text":"Resource Allocation"},{"level":2,"text":"Resource Schedule"},{"level":2,"text":"Resource Management"},{"level":2,"text":"Project Schedule"},{"level":2,"text":"Project Timeline"},{"level":2,"text":"Milestone Schedule"},{"level":2,"text":"Critical Path Analysis"},{"level":2,"text":"Schedule Baseline"},{"level":2,"text":"Quality Management Plan"},{"level":2,"text":"Quality Objectives"},{"level":2,"text":"Quality Metrics"},{"level":2,"text":"Quality Control Activities"},{"level":2,"text":"Quality Assurance Activities"},{"level":2,"text":"Risk Management Plan"},{"level":2,"text":"Risk Identification"},{"level":2,"text":"Risk Assessment"},{"level":2,"text":"Risk Response Planning"},{"level":2,"text":"Risk Monitoring and Control"},{"level":2,"text":"Communication Plan"},{"level":2,"text":"Stakeholder Identification"},{"level":2,"text":"Communication Channels"},{"level":2,"text":"Communication Objectives"},{"level":2,"text":"Communication Frequency"},{"level":2,"text":"Stakeholder Management Plan"},{"level":2,"text":"Stakeholder Analysis"},{"level":2,"text":"Stakeholder Engagement Plan"},{"level":2,"text":"Stakeholder Communication Plan"},{"level":2,"text":"Project Baselines"},{"level":2,"text":"Scope Baseline"},{"level":2,"text":"Schedule Baseline"},{"level":2,"text":"Cost Baseline"},{"level":2,"text":"Project Budget"},{"level":2,"text":"Budget Breakdown"},{"level":2,"text":"Cost Estimation"},{"level":2,"text":"Budget Tracking"},{"level":2,"text":"Project Plan Approval"},{"level":2,"text":"Approval Process"},{"level":2,"text":"Approvals Required"},{"level":2,"text":"Signatories"},{"level":2,"text":"Appendices"},{"level":2,"text":"Glossary of Terms"},{"level":2,"text":"List of Acronyms"},{"level":2,"text":"Change Management Plan"},{"level":2,"text":"Issue Management Plan"},{"level":2,"text":"Procurement Plan"},{"level":2,"text":"Training Plan"},{"level":2,"text":"Other Relevant Plans and Documents"}]},{"id":"g113","part":12,"title":"Procurement Process Overview","blocks":[{"level":1,"text":"Procurement Process"},{"level":2,"text":"Secures goods and services from other companies"},{"level":1,"text":"The procurement process has dedicated professionals who specialize in it"},{"level":1,"text":"Steps of the Procurement Process"},{"level":2,"text":"Define requirements"},{"level":2,"text":"PM defines the procurement requirements to meet the project's objective"},{"level":2,"text":"Submit a purchase requisition"},{"level":2,"text":"PM requests assistance from the procurement team to acquire resources"},{"level":2,"text":"Complete the solicitation process"},{"level":2,"text":"Procurement specialist prepares a request to solicit quotes, bids, or proposals from vendors"},{"level":2,"text":"Evaluate and select vendors"},{"level":2,"text":"Evaluation committee evaluates and scores vendor proposals based on predetermined objective criteria"},{"level":2,"text":"Manage orders"},{"level":2,"text":"Procurement specialist or PM generates POs, and the vendor begins work in response"},{"level":2,"text":"Manage records and payments"},{"level":2,"text":"Accounting, purchasing, and procurement teams review order records to identify discrepancies"},{"level":1,"text":"Common Procurement Artifacts"},{"level":2,"text":"Purchase Order (PO)"},{"level":2,"text":"A request made by a customer for specific goods or services, initiating a transaction"},{"level":2,"text":"Master Service Agreement (MSA) / Contract"},{"level":2,"text":"Comprehensive document outlining the terms of the vendor- buyer relationship"},{"level":2,"text":"Contract establishes an agreement to purchase something, while a PO fulfills the contract by initiating specific purchases"},{"level":2,"text":"Procurement Contract"},{"level":2,"text":"Work together with PO to ensure that the agreed-upon terms are met"},{"level":1,"text":"Lease"},{"level":2,"text":"Fixed-term contract paid with an initial fee and regular recurring payments for the duration of the lease"},{"level":2,"text":"At the end of the contract, you generally have three options: return the asset to the owner, renew the lease, or purchase the asset"},{"level":1,"text":"Subscription/Pay-as-you-go"},{"level":2,"text":"All-inclusive rental model paid with a flat fee for access to a resource for a set duration"},{"level":2,"text":"Subscription works well as a low-maintenance option with the latest models or for short-term or low-volume use, pilot activities, or a small budget"},{"level":2,"text":"The subscription provider pays for maintenance and repairs"},{"level":1,"text":"Different Exploratory Documents"},{"level":2,"text":"Requests For Information (RFI)"},{"level":2,"text":"A document used to gather information about potential vendors and capabilities"},{"level":2,"text":"Request For Proposal"},{"level":2,"text":"A formal document that outlines an organization's needs and solicits proposals from vendors to provide solutions or services to meet those needs"},{"level":2,"text":"Request For Bids (RFB)"},{"level":2,"text":"Formal document that solicits bids from vendors for the supply of goods or services"},{"level":2,"text":"Requests For Quote (RFQ)"},{"level":2,"text":"Formal document that solicits quotes from vendors for the supply of goods or services"}]},{"id":"g114","part":12,"title":"Evaluating Solutions","blocks":[{"level":1,"text":"Statement of Work (SOW)"},{"level":2,"text":"Formal document that specifies the work that a vendor is required to complete"},{"level":2,"text":"3 Main Types of Statement of Work"},{"level":2,"text":"Design Statement of Work"},{"level":2,"text":"Prescriptive and details the specific process and resources required to deliver the work"},{"level":2,"text":"Functional Statement of Work"},{"level":2,"text":"Outcome-focused and describes only the requirements of the finished product"},{"level":2,"text":"Performance Statement of Work"},{"level":2,"text":"Focuses on the expected outcomes along with minimum performance standards"},{"level":1,"text":"Terms of Reference (TOR)"},{"level":2,"text":"A version of the statement of work that contains the same information but focuses on delivering work"},{"level":2,"text":"TOR is a formal document that creates a shared understanding of a group's scope of work or expectations"},{"level":1,"text":"The elements of both an SOW and a TOR are the same which includes"},{"level":2,"text":"Background and Overview"},{"level":2,"text":"Requirements"},{"level":2,"text":"Deliverables"},{"level":2,"text":"Standards for Acceptance"},{"level":2,"text":"Schedule"},{"level":2,"text":"Payment Terms"},{"level":1,"text":"Procurement specialist conducts market research about a product or service, suppliers, and industry trends"},{"level":1,"text":"Market research can be conducted in several ways"},{"level":2,"text":"RFI"},{"level":2,"text":"Networking"},{"level":2,"text":"Research Firms"},{"level":2,"text":"Demo or Conferences"},{"level":2,"text":"Internal Research"},{"level":1,"text":"Competitive analysis is often discussed alongside market research as it looks at the same information from a different angle"},{"level":2,"text":"While market research identifies a list of potential vendors, competitive analysis compares them against each other and evaluates how firms are competing in the market"},{"level":1,"text":"Conducting market research and competitive analysis are practical recurring procurement activities"},{"level":1,"text":"Reviewing options provides insight for a decision to switch vendors or renegotiate terms"},{"level":1,"text":"Evaluation considerations includes alternative solutions and current vendor options"},{"level":1,"text":"Predetermined Client"},{"level":2,"text":"A model user or a preferred configuration that optimizes the product's performance"},{"level":1,"text":"Capital Expenses and Operational Expenses (CapEx and OpEx) are two types of expenses in an organization"},{"level":2,"text":"Capital Expenses (CapEx)"},{"level":2,"text":"Permanent assets like data centers, vehicles, and equipment that fall outside the operating budget"},{"level":2,"text":"Operational Expenses (OpEx)"},{"level":2,"text":"Regular expenses like salaries, taxes, subscriptions, rentals, and utilities that are built into the budget and do not depreciate"},{"level":1,"text":"Ensure that the vendor has the capacity, capability, and interest to deliver the project requirements"}]},{"id":"g115","part":12,"title":"Evaluation Techniques","blocks":[{"level":1,"text":"Vendor selection is a crucial process that requires objectivity, fairness, and ethical practices"},{"level":1,"text":"To select vendors objectively, an evaluation panel can use multiple vendor evaluation techniques"},{"level":2,"text":"The evaluation method and source selection criteria are determined before sending out the Request for Proposal (RFP) to ensure a fair vendor selection process"},{"level":2,"text":"Several evaluation techniques"},{"level":2,"text":"Best Value vs Lowest Cost"},{"level":2,"text":"Cost-benefit Analysis"},{"level":1,"text":"When evaluating a vendor, it's important to consider whether they have the capacity to meet your contract demands"},{"level":2,"text":"Physical Capacity"},{"level":2,"text":"Refers to the vendor's ability to produce the required volume of goods or services, including units sold, consulting hours, or any other relevant measure"},{"level":2,"text":"The evaluation of physical capacity should also consider the vendor's overall business"},{"level":2,"text":"Consider the risk of delays or cancellations if scheduling conflicts arise"},{"level":2,"text":"Physical capacity evaluations should take into account both current and long-term growth projections"},{"level":1,"text":"In addition to physical capacity, it's essential to evaluate a vendor's financial stability"},{"level":2,"text":"Financial Stability Evaluation"},{"level":2,"text":"Involves assessing the vendor's overall financial health or viability"},{"level":2,"text":"Financial evaluations should include a review of the following"},{"level":2,"text":"Financial Statements"},{"level":2,"text":"Credit Documentation"},{"level":2,"text":"Public Documentation"},{"level":2,"text":"Consider the vendor's governing body to gain insight into how company finances are managed"},{"level":1,"text":"Qualifying a vendor involves assessing their ability to meet the needs of the buying organization"},{"level":2,"text":"This evaluation process requires vendors to demonstrate their capacity to deliver goods or services that meet the required standards"},{"level":2,"text":"Qualification may involve assessing the condition of a vendor's facilities, as well as the expertise and qualifications of their staff"},{"level":1,"text":"Fit Evaluation Techniques"},{"level":2,"text":"Vendor Demonstration"},{"level":2,"text":"Interactive session where a vendor showcases their solution"},{"level":2,"text":"Technical Approach"},{"level":2,"text":"Involves comparing vendor submissions to the project requirements"},{"level":2,"text":"Vendors offering products beyond the requirements do not receive a higher score, and they do not directly compete against each other"},{"level":2,"text":"References"},{"level":2,"text":"Reference checks are conducted with the vendor's other clients"},{"level":1,"text":"The procurement specialist asks about the client's experience with the vendor, their interaction, technology used, and performance, including responsiveness, work quality, on-time performance, and cost management"}]},{"id":"g116","part":12,"title":"Procurement Contracts","blocks":[{"level":1,"text":"3 Main Types of Contracts"},{"level":2,"text":"Fixed-Price Contract (Lump Sum Contract)"},{"level":2,"text":"Establishes a set price for a fixed scope of work and places most of the contract risk on the vendor"},{"level":2,"text":"A fixed-price contract is suitable when the contract's scope remains unchanged"},{"level":2,"text":"3 Types of Fixed-Price Contracts"},{"level":2,"text":"Firm Fixed-Price (FFP)"},{"level":2,"text":"A model where the buyer agrees to pay a fixed price for a specific product or set of products"},{"level":2,"text":"FFP contracts are suitable for well-defined products with clear specifications"},{"level":2,"text":"Fixed-Price Incentive Fee (FPIF)"},{"level":2,"text":"A buyer can add incentives to a fixed-price contract"},{"level":2,"text":"Incentives could be based on quality, safety, or other measurable targets"},{"level":2,"text":"Measurable performance is crucial as it allows both parties to agree on the payment schedule"},{"level":2,"text":"FPIF contracts work best when the buyer has a budget for stretch goals"},{"level":2,"text":"Fixed-Price with Economic Price Adjustment (FP-EPA)"},{"level":2,"text":"A fixed-price contract that takes into account inflation costs"},{"level":2,"text":"Cost-Plus Contract / Cost-Reimbursable Contract"},{"level":2,"text":"Reimburses the vendor for all resource costs incurred in completing the work and adds a fee to cover the vendor's profit margin"},{"level":2,"text":"The buyer is responsible for any inefficient resource management on the part of the vendor"},{"level":2,"text":"Effective expense tracking is critical to controlling costs in a cost- reimbursable contract"},{"level":2,"text":"Cost-Plus Award Fee (CPAF)"},{"level":2,"text":"Additional fee is awarded based on the vendor's performance during the project"},{"level":2,"text":"The CPAF contract incentivizes the vendor to meet the buyer's needs by offering a bonus fee if the vendor exceeds expectations"},{"level":2,"text":"Cost-Plus Incentive Fee (CPIF) Contract"},{"level":2,"text":"Contract that offers vendors an incentive to complete a project under specific circumstances"},{"level":2,"text":"Time-and-Material (T&M) Contract"},{"level":2,"text":"Pays for the actual hours worked by the vendor at a predetermined hourly rate"},{"level":2,"text":"Buyers prefer T&M contracts when there is confidence in the vendor's ability to complete the project within budget"},{"level":2,"text":"Cost-Plus Percentage of Cost (CPPC) Contract"},{"level":2,"text":"A vendor receives a fee equal to a percentage of all costs"},{"level":2,"text":"CPPC contract is beneficial when the buyer wants the flexibility to change materials or adjust the scope of work as the project progresses"},{"level":2,"text":"Hybrid Contract"},{"level":2,"text":"Like unit price and time and materials"},{"level":2,"text":"It is suitable for purchasing repetitive work when the quantity or scope is unknown at the project's outset"},{"level":2,"text":"Time and materials (T&M) contract are suitable for projects with a fixed cost and flexible scope"},{"level":2,"text":"Buyers prefer T&M contracts to control the maximum cost but retain flexibility during project execution"}]},{"id":"g117","part":12,"title":"Contract Terms","blocks":[{"level":1,"text":"There are some contract terms that you need to know before you start procuring solutions like warranties and non-disclosure agreements"},{"level":1,"text":"Including a warranty in a procurement agreement can mitigate risk for the buyer by providing the vendor's assurance to address any defects"},{"level":1,"text":"Warranty"},{"level":2,"text":"Outlines the duration of time the vendor anticipates the product to be free from flaws and specifies the course of action in the event of a malfunction"},{"level":2,"text":"Common Elements of Warranty"},{"level":2,"text":"Length"},{"level":2,"text":"The warranty period is specified, usually lasting for a defined period, such as one year"},{"level":2,"text":"Scope"},{"level":2,"text":"A warranty usually covers defects resulting from the production process, such as sudden Wi-Fi antenna failure in a cell phone"},{"level":2,"text":"Remediation"},{"level":2,"text":"The vendor outlines the course of action in the event of a defect, often including a refund, replacement, or both"},{"level":2,"text":"Limitations and Exclusions"},{"level":2,"text":"The vendor specifies their responsibility boundaries, including limitations and excluded situations"},{"level":2,"text":"Commencement"},{"level":2,"text":"The commencement clause is relevant for projects, such as a software implementation warranty in a procurement agreement that offers free remediation for failures"},{"level":1,"text":"Non-Disclosure Agreements"},{"level":2,"text":"Enables the exchange of sensitive or valuable information with a certain level of confidence that it will not be divulged"},{"level":2,"text":"Several scenarios may require an NDA which includes"},{"level":2,"text":"New product development"},{"level":2,"text":"If both parties are working together to create a new product or design, they should sign an NDA"},{"level":2,"text":"Non-public information"},{"level":2,"text":"If the vendor has access to any information that is not publicly available, an NDA can protect proprietary and sensitive data"},{"level":2,"text":"Facilities"},{"level":2,"text":"If the vendor will have access to your facilities where they may see proprietary processes, equipment, or information, request an NDA"},{"level":2,"text":"Consulting"},{"level":2,"text":"Consultants should sign an NDA for their clients because the consulting process involves sharing non-public information"},{"level":1,"text":"Once the contracts have been signed and the project is underway, the PM assumes a primary role in managing the vendor relationship"},{"level":1,"text":"The PM possesses a deeper understanding of the project's deliverables, quality standards, and customer expectations"},{"level":1,"text":"PM will engage in several vendor management activities throughout the project"},{"level":2,"text":"Rules of Engagement"},{"level":2,"text":"The operating agreements that dictate how the vendor and project team will collaborate to execute a project"},{"level":2,"text":"Rules of engagement are crucial for any project, especially those that involve diverse groups of individuals who haven't worked together before"},{"level":2,"text":"Performance Monitoring"},{"level":2,"text":"The PM also has the ability to monitor and evaluate a vendor's quantifiable performance, such as their compliance with SLAs"},{"level":2,"text":"It is important to collaborate with the vendor to adjust targets, if necessary, as initial targets can often be overly ambitious"},{"level":2,"text":"Approval of Deliverables"},{"level":2,"text":"Involves a thorough review of the work submitted, ensuring it meets the project's quality standards"},{"level":2,"text":"Each deliverable should contribute to the project's overall completion, and any work that fails to do so must be evaluated Managing Project Execution"}]},{"id":"g118","part":13,"title":"Managing Project Execution","blocks":[{"level":1,"text":"The beginning of the execution phase marks a significant point in the project"},{"level":1,"text":"During the discovery, initiation, and planning phases, the project manager takes the lead and drives most of the project's activities"},{"level":1,"text":"To keep track of this information effectively, the team must plan how they will organize it and commit to following the process"},{"level":1,"text":"The project manager is responsible for monitoring the project's progress"},{"level":2,"text":"They gather data, analyze reports, and measure progress, reporting to stakeholders and ensuring that communication is flowing smoothly"},{"level":1,"text":"The project manager receives change requests, analyzes them, and adjusts the project plan accordingly"},{"level":1,"text":"Project manager enables the team to deliver the plan, providing positive support and constructive feedback, maintaining momentum, clearing impediments, and trusting the team members to deliver their work"}]},{"id":"g119","part":13,"title":"Project Momentum","blocks":[{"level":1,"text":"Managing a project is like overseeing an extensive, intricate system with numerous components"},{"level":2,"text":"This requires a combination of project management and leadership skills, and a genuine desire to support others"},{"level":1,"text":"To establish and sustain project momentum, consider implementing these methods"},{"level":2,"text":"Starting Strong"},{"level":2,"text":"Setting the Pace"},{"level":2,"text":"Looking Forward"},{"level":2,"text":"Motivating the Team"},{"level":1,"text":"To ensure project success, it's crucial to begin with a clear vision"},{"level":2,"text":"This means understanding why the project is important and what it needs to achieve"},{"level":1,"text":"Project sponsors, stakeholders, and team members must all comprehend why the company has chosen to invest in this project above all others"},{"level":1,"text":"The PM also sets the pace by enforcing deadlines and establishes clear expectations that the team will fulfill them"},{"level":2,"text":"They anticipate and eliminate the roadblocks to keep the project on track"},{"level":2,"text":"They understand the value of the project more than anyone else and make sure the team comprehends its significance too"},{"level":1,"text":"It's also about creating a conducive project environment that doesn't drain their energy"},{"level":1,"text":"The PM should solicit feedback from the team to improve the system they work in"}]},{"id":"g120","part":13,"title":"Requirements Traceability Matrix (RTM)","blocks":[{"level":1,"text":"Requirements Traceability Matrix (RTM)"},{"level":2,"text":"Document that maps and tracks the relationship between requirements, design, development, testing, and deployment"},{"level":2,"text":"RTM helps to ensure that all requirements of a project are met and that the project is delivered on time and within budget"},{"level":2,"text":"The RTM also provides a transparent view of the project progress"},{"level":1,"text":"Traceability"},{"level":2,"text":"Refers to the ability to follow the path of something"},{"level":2,"text":"Traceability is crucial for solving problems and updating systems"},{"level":2,"text":"In some instances, traceability is a legal requirement"},{"level":1,"text":"The bidirectional traceability of an RTM is crucial as it allows tracing work from requirements to tests and vice versa"},{"level":2,"text":"Forward Traceability"},{"level":2,"text":"Goes from the original requirements to the resulting tests"},{"level":2,"text":"Backward Traceability"},{"level":2,"text":"Starts with the tests and goes back to the requirements"},{"level":1,"text":"An RTM provides many other advantages to the project"},{"level":2,"text":"Useful for impact analysis as it centralizes all requirements information"},{"level":2,"text":"Helps determine if the project is meeting requirements"},{"level":2,"text":"Simplifies audit and quality processes"},{"level":2,"text":"Identifies which requirements are not being met"}]},{"id":"g121","part":13,"title":"Progress Tracking Tools","blocks":[{"level":1,"text":"Project management application enables to track projects and plan required activities"},{"level":1,"text":"Monitor Progress"},{"level":2,"text":"Enables project managers to monitor progress on a project and ensures that tasks are being completed on schedule"},{"level":1,"text":"Improve Resource Allocation"},{"level":2,"text":"Project managers can allocate resources and ensure that team members are working efficiently"},{"level":1,"text":"Accurately Estimate Project Timelines"},{"level":2,"text":"Tracking the time, it takes to complete tasks can help project managers make accurate estimates for future projects"},{"level":1,"text":"Enhance Communication"},{"level":2,"text":"Used to generate reports and other visualizations that provide valuable insights into project progress"},{"level":1,"text":"Application for Time Tracking"},{"level":2,"text":"Monitors the time needed to complete tasks in detail"},{"level":1,"text":"Project and Time Tracking Application"},{"level":2,"text":"Include useful features such as report generation, which simplifies communication processes"},{"level":2,"text":"Project Management"},{"level":2,"text":"Break down work, organize resources, manage dependencies, and control the project schedule"},{"level":2,"text":"Time Tracking"},{"level":2,"text":"Plan the work day and report progress"},{"level":1,"text":"Task Board"},{"level":2,"text":"A visual tool for tracking tasks"}]},{"id":"g122","part":13,"title":"Version Control","blocks":[{"level":1,"text":"Version control software is utilized by software development and DevOps teams to streamline their development and release processes"},{"level":2,"text":"They keep a record of what was changed, when it was changed, and who made the change"},{"level":1,"text":"A software product's source code is extensive and includes numerous interdependencies"},{"level":1,"text":"Version control tools operate in the background, tracking all changes made to the source code"},{"level":1,"text":"Without version control, the burden of traceability falls on developers"},{"level":1,"text":"Testing is also likely to take longer, as resolving failed tests involves searching through developers' offline files to identify changes"},{"level":1,"text":"Version Control is an essential tool for any IT project manager"}]},{"id":"g123","part":13,"title":"Logs","blocks":[{"level":1,"text":"Issue logs, defect logs, and change logs are important for an IT project manager for several reasons"},{"level":2,"text":"Logs allow the IT project manager to track the progress of the project"},{"level":2,"text":"Logs also help us identify patterns in the types of issues, defects, and changes that occur"},{"level":2,"text":"Issue and defect logs help the IT project manager to quickly identify and resolve issues and defects"},{"level":2,"text":"Change logs provide a record of all changes made to the project"},{"level":2,"text":"When the changes were made"},{"level":2,"text":"Who made them"},{"level":2,"text":"Why"},{"level":1,"text":"Issue Log"},{"level":2,"text":"A tool that tracks and manages issues that arise in a project"},{"level":2,"text":"Each issue is recorded with a description, date found, and the person who found it"},{"level":2,"text":"Common fields in an issue log include"},{"level":2,"text":"Issue Number"},{"level":2,"text":"Description"},{"level":2,"text":"Priority"},{"level":2,"text":"Impact"},{"level":2,"text":"Raised By (the person who reported the issue)"},{"level":2,"text":"Owner (the person responsible for fixing the issue)"},{"level":2,"text":"Status"},{"level":2,"text":"Date Found"},{"level":2,"text":"Date Closed"},{"level":2,"text":"Comments"},{"level":2,"text":"Issue log ensures that issues are not overlooked and helps to prioritize them based on their impact on the project"},{"level":1,"text":"Defect Log"},{"level":2,"text":"Used primarily in software projects to track and manage issues where a product was built to meet a requirement but fails to do so"},{"level":2,"text":"It should provide enough information for the engineer to research, recreate, and resolve the defect"},{"level":2,"text":"Failed test"},{"level":2,"text":"Environment or inputs"},{"level":2,"text":"System’s behavior"},{"level":2,"text":"Screenshots"},{"level":2,"text":"Recordings"},{"level":2,"text":"Log files"},{"level":2,"text":"Common fields in a defect log include"},{"level":2,"text":"Defect Number"},{"level":2,"text":"Description"},{"level":2,"text":"Failed Test(s)"},{"level":2,"text":"How to Reproduce"},{"level":2,"text":"Priority"},{"level":2,"text":"Impact"},{"level":2,"text":"Found By"},{"level":2,"text":"Owner (Person responsible for resolving the defect)"},{"level":2,"text":"Status"},{"level":2,"text":"Date Found"},{"level":2,"text":"Date Fixed"},{"level":2,"text":"Comments"},{"level":2,"text":"Defect log ensures that defects are resolved, and the product meets the requirements"},{"level":1,"text":"Change Log"},{"level":2,"text":"Refers to a record of alterations made to a project plan"},{"level":2,"text":"Changes are a common occurrence in any project which includes"},{"level":2,"text":"Addition of a new feature"},{"level":2,"text":"Departure of a team member"},{"level":2,"text":"Common fields in a change log include"},{"level":2,"text":"Change Number"},{"level":2,"text":"Description"},{"level":2,"text":"Type of Request"},{"level":2,"text":"Priority"},{"level":2,"text":"Impact"},{"level":2,"text":"Requested By"},{"level":2,"text":"Owner"},{"level":2,"text":"Status"},{"level":2,"text":"Date of Request or Identification"},{"level":2,"text":"Date of Completion"},{"level":2,"text":"Comments"},{"level":1,"text":"PM often uses a single register to record risks, issues, changes, and defects"}]},{"id":"g124","part":13,"title":"Burnup and Burndown Charts","blocks":[{"level":1,"text":"Regular updates prepared in advance allow for quick and efficient responses"},{"level":1,"text":"Burnup and burndown charts are useful tools for managing project scope and time"},{"level":2,"text":"It tracks two key values"},{"level":2,"text":"Target Work"},{"level":2,"text":"Actual Work"},{"level":1,"text":"Burnup Chart"},{"level":2,"text":"Tracks the total amount of work completed each day"},{"level":2,"text":"Burnup charts are most effective when the project's scope is fixed but the timeline is flexible"},{"level":1,"text":"Burndown Chart"},{"level":2,"text":"Tracks the amount of remaining work each day"},{"level":2,"text":"Burndown charts are best suited for projects with fixed timelines"}]},{"id":"g125","part":13,"title":"Velocity and Throughput Charts","blocks":[{"level":1,"text":"Velocity Chart"},{"level":2,"text":"Measures how many story points a team can complete within a given sprint or iteration"},{"level":2,"text":"The velocity chart helps the IT project manager measure and manage the team's productivity over time"},{"level":1,"text":"Throughput Chart"},{"level":2,"text":"Measures the number of work items completed per iteration, regardless of complexity or effort required"},{"level":2,"text":"Teams can use the data to identify capacity, prioritize work items, and plan workload for upcoming sprints"},{"level":2,"text":"Using a throughput chart, the IT PM is able to track the team's performance and set goals for upcoming sprints"},{"level":1,"text":"Both velocity and throughput charts are valuable for agile teams"},{"level":2,"text":"Provide a way to measure the team’s progress and performance"},{"level":2,"text":"Identify areas to improve, adjust workload, and plan capacity for future sprints"},{"level":2,"text":"Maintain a steady pace of work by setting goals based on their historical performance"},{"level":2,"text":"Enable agile teams to work efficiently, deliver projects on time, and improve performance"}]},{"id":"g126","part":13,"title":"Meetings","blocks":[{"level":1,"text":"Team Status Meeting / Team Touchpoint Meeting"},{"level":2,"text":"A recurring meeting that's used to update the overall progress of the project and resolve any issues"},{"level":2,"text":"Team status meetings are working meetings"},{"level":2,"text":"An effective agenda for a team meeting should include the following topics"},{"level":2,"text":"Open action items"},{"level":2,"text":"Status updates"},{"level":2,"text":"Task updates"},{"level":2,"text":"Open risks and issues"},{"level":2,"text":"New risks and issues"},{"level":2,"text":"Performance related to scope, time, and cost"},{"level":2,"text":"Updates on RACI (Responsible, Accountable, Consulted, and Informed) assignments"},{"level":2,"text":"Dashboards contain detailed project information and resemble a simple interface or dashboard"},{"level":1,"text":"Sprint Planning Meeting"},{"level":2,"text":"The team will plan the work for the upcoming sprint"},{"level":2,"text":"At the beginning of each sprint, the team will come together to plan their work for the upcoming sprint"},{"level":2,"text":"Set the sprint capacity based on historical throughput or velocity"},{"level":2,"text":"Review the top priority items in the backlog and break them down into smaller work items"},{"level":2,"text":"The agenda for a sprint planning meeting should include the following"},{"level":2,"text":"Review of project goals"},{"level":2,"text":"Discussion of any issues, defects, or changes that could affect the project plan"},{"level":2,"text":"Setting the sprint target (velocity or throughput)"},{"level":2,"text":"Development of the sprint backlog"},{"level":1,"text":"Stakeholder Meeting"},{"level":2,"text":"Held to report the project's overall progress, gather feedback, and highlight upcoming deliverables"},{"level":1,"text":"External Stakeholder Meeting"},{"level":2,"text":"Requires restraint and positivity, focuses on successes, and discusses only externally visible deliverables and milestones"},{"level":2,"text":"The external stakeholder meeting agenda includes"},{"level":2,"text":"Project status"},{"level":2,"text":"Upcoming releases"},{"level":2,"text":"Major milestones and deadlines"},{"level":2,"text":"Next steps"},{"level":2,"text":"Feedback solicitation"},{"level":1,"text":"Internal Stakeholder Meeting"},{"level":2,"text":"Includes critical roadblocks, risks and issues, major milestones and deadlines, scope, time, and cost performance, next steps, and feedback solicitation"},{"level":1,"text":"Conditional Meeting"},{"level":2,"text":"Occurs on request or when support is needed from a specific group"},{"level":2,"text":"3 Types of Conditional Meeting"},{"level":2,"text":"Phase Gate Meeting"},{"level":2,"text":"Held at the end of each project phase to review the deliverables, assess the project's progress, and decide to continue with the project or not"},{"level":2,"text":"Change Control Meeting"},{"level":2,"text":"Held to review and approve any proposed changes to the project's scope, schedule, or budget"},{"level":2,"text":"Ad Hoc Reporting"},{"level":2,"text":"Reporting that is performed on an as-needed basis"}]},{"id":"g127","part":13,"title":"Providing Feedback","blocks":[{"level":1,"text":"The PM's main responsibility is to optimize the project's performance by tracking progress and making necessary adjustments to the project management plan"},{"level":1,"text":"Positive Feedback"},{"level":2,"text":"Recognizes effective project contributions"},{"level":1,"text":"Negative Feedback"},{"level":2,"text":"Highlights areas that require improvement"},{"level":1,"text":"2 Golden Rules"},{"level":2,"text":"Treat others as you want to be treated"},{"level":2,"text":"Praise in public and correct in private"},{"level":1,"text":"A feedback loop is a process cycle where you inspect and improve a system"},{"level":2,"text":"Gather Feedback"},{"level":2,"text":"Analyze Feedback"},{"level":2,"text":"Act on Feedback"},{"level":2,"text":"Follow Up"},{"level":1,"text":"Feedback sources which you can derive insights from, tying into our first step of the feedback process"},{"level":2,"text":"Performance Metrics"},{"level":2,"text":"Generate project performance reports that can provide valuable feedback"},{"level":2,"text":"Stakeholder Comments"},{"level":2,"text":"Stakeholders will provide feedback in meetings, emails, and informal conversations"},{"level":2,"text":"Observation"},{"level":2,"text":"Look for how each person is contributing to the product and take note of any areas where improvements can be made"},{"level":2,"text":"Teammate Feedback"},{"level":2,"text":"Solicit comments from teammates through formal feedback systems or one-on-one meetings"},{"level":2,"text":"Lessons Learned"},{"level":2,"text":"Monitor the feedback and look for trends that support other feedback you've gathered"},{"level":1,"text":"Providing feedback is a skill"},{"level":1,"text":"When someone does something well, be specific and praise their actions"},{"level":1,"text":"Be sensitive to potential reactions"},{"level":1,"text":"If the feedback raises legal, safety, or human resources issues, the relevant department and others outlined in your company policy should be informed"},{"level":1,"text":"Timely feedback is more valuable than delayed feedback"},{"level":1,"text":"Share feedback close to the event so that team members can learn and adjust their behaviors accordingly"},{"level":1,"text":"Some feedback is best discussed in a group setting, such as functional feedback about a work item"},{"level":1,"text":"Other feedback might need to be delivered privately, so consider using asynchronous methods like email"},{"level":1,"text":"Imagine yourself in the recipient's position and think about how you would like to receive the feedback"},{"level":1,"text":"Be comfortable with giving feedback Resolve Issues"}]});
